B.alo=s(["\u0627\u062e\u062a\u0631 \u0645\u0647\u0645\u0629 \u0623\u062c\u0651\u0644\u062a\u0647\u0627 \u0637\u0648\u064a\u0644\u064b\u0627\u060c \u0648\u0627\u0639\u0645\u0644 \u0639\u0644\u064a\u0647\u0627 20 \u062f\u0642\u064a\u0642\u0629 \u0641\u0642\u0637.","\u0627\u0643\u062a\u0628 \u0647\u062f\u0641\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0644\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u060c \u0648\u0636\u0639\u0647 \u0623\u0645\u0627\u0645 \u0639\u064a\u0646\u064a\u0643.","\u0627\u0628\u062f\u0623 \u064a\u0648\u0645\u0643 \u0628\u0623\u0635\u0639\u0628 \u0645\u0647\u0645\u0629 \u0642\u0628\u0644 \u0623\u064a \u0634\u064a\u0621 \u0622\u062e\u0631.","\u0623\u0631\u0633\u0644 \u0631\u0633\u0627\u0644\u0629 \u062a\u0634\u062c\u064a\u0639 \u0644\u0634\u062e\u0635 \u064a\u0645\u0631\u0651 \u0628\u0645\u0631\u062d\u0644\u0629 \u0635\u0639\u0628\u0629."],t.s)
B.aw5=s(["\u0627\u0643\u062a\u0628 \u062b\u0644\u0627\u062b\u0629 \u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0635\u063a\u064a\u0631\u0629 \u062d\u0642\u0642\u062a\u0647\u0627 \u0647\u0630\u0627 \u0627\u0644\u0634\u0647\u0631.","\u062a\u0639\u0644\u0651\u0645 \u0645\u0647\u0627\u0631\u0629 \u062c\u062f\u064a\u062f\u0629 \u0644\u0645\u062f\u0629 15 \u062f\u0642\u064a\u0642\u0629 \u0627\u0644\u064a\u0648\u0645.","\u0631\u0627\u062c\u0639 \u062e\u0637\u0623\u064b \u0648\u0642\u0639\u062a \u0641\u064a\u0647 \u0645\u0624\u062e\u0631\u064b\u0627\u060c \u0648\u0627\u0643\u062a\u0628 \u062f\u0631\u0633\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0645\u0646\u0647.","\u0642\u0633\u0651\u0645 \u0647\u062f\u0641\u0643 \u0627\u0644\u0643\u0628\u064a\u0631 \u0625\u0644\u0649 \u062b\u0644\u0627\u062b \u062e\u0637\u0648\u0627\u062a \u0635\u063a\u064a\u0631\u0629\u060c \u0648\u0646\u0641\u0651\u0630 \u0627\u0644\u0623\u0648\u0644\u0649."],t.s)
B.aqf=s(["\u0642\u0628\u0644 \u0623\u0646 \u062a\u0631\u062f\u0651 \u0639\u0644\u0649 \u0623\u064a \u0646\u0642\u0627\u0634 \u0627\u0644\u064a\u0648\u0645\u060c \u062e\u0630 \u0646\u0641\u0633\u064b\u0627 \u0639\u0645\u064a\u0642\u064b\u0627 \u0648\u0641\u0643\u0651\u0631 \u062b\u0644\u0627\u062b \u062b\u0648\u0627\u0646\u064d.","\u0627\u0633\u0623\u0644 \u0634\u062e\u0635\u064b\u0627 \u0623\u0643\u0628\u0631 \u0645\u0646\u0643 \u0633\u0646\u064b\u0651\u0627 \u0639\u0646 \u0623\u0647\u0645 \u062f\u0631\u0633 \u062a\u0639\u0644\u0651\u0645\u0647 \u0641\u064a \u062d\u064a\u0627\u062a\u0647.","\u0627\u0643\u062a\u0628 \u0642\u0631\u0627\u0631\u064b\u0627 \u062a\u062d\u062a\u0627\u062c \u0623\u0646 \u062a\u062a\u062e\u0630\u0647\u060c \u0645\u0639 \u0625\u064a\u062c\u0627\u0628\u064a\u0627\u062a\u0647 \u0648\u0633\u0644\u0628\u064a\u0627\u062a\u0647.","\u0627\u0633\u062a\u0645\u0639 \u0627\u0644\u064a\u0648\u0645 \u0623\u0643\u062b\u0631 \u0645\u0645\u0627 \u062a\u062a\u0643\u0644\u0645."],t.s)
B.aFT=s(["\u0627\u0642\u0631\u0623 \u0639\u0634\u0631 \u0635\u0641\u062d\u0627\u062a \u0645\u0646 \u0643\u062a\u0627\u0628 \u0645\u0641\u064a\u062f.","\u062a\u0639\u0644\u0651\u0645 \u0643\u0644\u0645\u0629 \u062c\u062f\u064a\u062f\u0629\u060c \u0648\u0627\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0641\u064a \u062c\u0645\u0644\u0629 \u0627\u0644\u064a\u0648\u0645.","\u0634\u0627\u0647\u062f \u062f\u0631\u0633\u064b\u0627 \u0642\u0635\u064a\u0631\u064b\u0627 \u0641\u064a \u0645\u062c\u0627\u0644 \u0644\u0627 \u062a\u0639\u0631\u0641 \u0639\u0646\u0647 \u0634\u064a\u0626\u064b\u0627.","\u0639\u0644\u0651\u0645 \u0634\u062e\u0635\u064b\u0627 \u0622\u062e\u0631 \u0634\u064a\u0626\u064b\u0627 \u062a\u0639\u0631\u0641\u0647 \u062c\u064a\u062f\u064b\u0627."],t.s)
B.ay4=s(["\u0627\u0643\u062a\u0628 \u062b\u0644\u0627\u062b\u0629 \u0623\u0634\u064a\u0627\u0621 \u062a\u0634\u0639\u0631 \u0628\u0627\u0644\u0627\u0645\u062a\u0646\u0627\u0646 \u0644\u0647\u0627 \u0627\u0644\u064a\u0648\u0645.","\u062a\u0630\u0643\u0651\u0631 \u0623\u0632\u0645\u0629 \u0645\u0631\u0651\u062a \u0628\u0643 \u0648\u062a\u062c\u0627\u0648\u0632\u062a\u0647\u0627\u060c \u0648\u0627\u0643\u062a\u0628 \u0643\u064a\u0641 \u062e\u0631\u062c\u062a \u0645\u0646\u0647\u0627.","\u0627\u0645\u0634\u0650 \u0639\u0634\u0631 \u062f\u0642\u0627\u0626\u0642 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u0637\u0644\u0642 \u062f\u0648\u0646 \u0647\u0627\u062a\u0641.","\u0642\u0644 \u0644\u0646\u0641\u0633\u0643 \u062c\u0645\u0644\u0629 \u0644\u0637\u064a\u0641\u0629 \u0643\u0645\u0627 \u062a\u0642\u0648\u0644\u0647\u0627 \u0644\u0635\u062f\u064a\u0642 \u0639\u0632\u064a\u0632."],t.s)
B.aCi=s(["\u0627\u0634\u0643\u0631 \u0634\u062e\u0635\u064b\u0627 \u0641\u064a \u0641\u0631\u064a\u0642\u0643 \u0623\u0648 \u0639\u0627\u0626\u0644\u062a\u0643 \u0639\u0644\u0649 \u062c\u0647\u062f \u0642\u0627\u0645 \u0628\u0647.","\u0627\u0633\u0623\u0644 \u0645\u0646 \u062d\u0648\u0644\u0643: \u0643\u064a\u0641 \u064a\u0645\u0643\u0646\u0646\u064a \u0623\u0646 \u0623\u0633\u0627\u0639\u062f\u0643 \u0627\u0644\u064a\u0648\u0645\u061f","\u0641\u0648\u0651\u0636 \u0645\u0647\u0645\u0629 \u0635\u063a\u064a\u0631\u0629 \u0644\u0634\u062e\u0635 \u0622\u062e\u0631 \u0648\u062b\u0650\u0642 \u0628\u0647.","\u0627\u062a\u062e\u0630 \u0642\u0631\u0627\u0631\u064b\u0627 \u0643\u0646\u062a \u062a\u0624\u062c\u0644\u0647\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0635\u063a\u064a\u0631\u064b\u0627."],t.s)
B.asP=s(["\u0627\u062d\u0630\u0641 \u062a\u0637\u0628\u064a\u0642\u064b\u0627 \u0644\u0627 \u062a\u0633\u062a\u062e\u062f\u0645\u0647 \u0645\u0646 \u0647\u0627\u062a\u0641\u0643.","\u062c\u0631\u0651\u0628 \u0623\u062f\u0627\u0629 \u0631\u0642\u0645\u064a\u0629 \u062c\u062f\u064a\u062f\u0629 \u062a\u0648\u0641\u0651\u0631 \u0639\u0644\u064a\u0643 \u0648\u0642\u062a\u064b\u0627.","\u062e\u0635\u0651\u0635 \u0633\u0627\u0639\u0629 \u0627\u0644\u064a\u0648\u0645 \u0628\u062f\u0648\u0646 \u0634\u0627\u0634\u0627\u062a.","\u0646\u0638\u0651\u0645 \u0645\u0644\u0641\u0627\u062a \u0647\u0627\u062a\u0641\u0643 \u0623\u0648 \u0635\u0648\u0631\u0643 \u0644\u0645\u062f\u0629 \u0639\u0634\u0631 \u062f\u0642\u0627\u0626\u0642."],t.s)
B.anY=s(["\u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0633\u0627\u0639\u062f \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0623\u0646 \u064a\u0634\u0631\u062d \u0644\u0643 \u0645\u0641\u0647\u0648\u0645\u064b\u0627 \u0635\u0639\u0628\u064b\u0627 \u0628\u0628\u0633\u0627\u0637\u0629.","\u0641\u0643\u0651\u0631 \u0641\u064a \u0645\u0647\u0645\u0629 \u0645\u062a\u0643\u0631\u0631\u0629 \u0641\u064a \u0639\u0645\u0644\u0643 \u064a\u0645\u0643\u0646 \u0623\u062a\u0645\u062a\u062a\u0647\u0627.","\u062a\u062d\u0642\u0651\u0642 \u0645\u0646 \u0645\u0639\u0644\u0648\u0645\u0629 \u0642\u0627\u0644\u0647\u0627 \u0644\u0643 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0645\u0646 \u0645\u0635\u062f\u0631 \u0645\u0648\u062b\u0648\u0642.","\u062a\u0639\u0644\u0651\u0645 \u0637\u0631\u064a\u0642\u0629 \u0643\u062a\u0627\u0628\u0629 \u0633\u0624\u0627\u0644 \u0648\u0627\u0636\u062d \u0648\u062f\u0642\u064a\u0642 \u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a."],t.s)
B.aFZ=s(["\u062a\u062d\u0642\u0651\u0642 \u0645\u0646 \u0645\u0635\u062f\u0631 \u062e\u0628\u0631 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0634\u0627\u0631\u0643\u0647 \u0627\u0644\u064a\u0648\u0645.","\u062a\u0627\u0628\u0639 \u0645\u0635\u062f\u0631\u064b\u0627 \u0625\u0639\u0644\u0627\u0645\u064a\u064b\u0627 \u064a\u0642\u062f\u0651\u0645 \u0648\u062c\u0647\u0629 \u0646\u0638\u0631 \u0645\u062e\u062a\u0644\u0641\u0629 \u0639\u0646 \u0631\u0623\u064a\u0643.","\u0642\u0644\u0651\u0644 \u0648\u0642\u062a \u062a\u0635\u0641\u0651\u062d \u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u064a\u0648\u0645 \u0625\u0644\u0649 \u0646\u0635\u0641 \u0633\u0627\u0639\u0629 \u0641\u0642\u0637.","\u0634\u0627\u0631\u0643 \u0645\u062d\u062a\u0648\u0649 \u0645\u0641\u064a\u062f\u064b\u0627 \u0628\u062f\u0644\u064b\u0627 \u0645\u0646 \u0645\u062d\u062a\u0648\u0649 \u0645\u062b\u064a\u0631 \u0644\u0644\u062c\u062f\u0644."],t.s)
B.azH=s(["\u0627\u062a\u0635\u0644 \u0628\u0635\u062f\u064a\u0642 \u0642\u062f\u064a\u0645 \u0644\u0645 \u062a\u0643\u0644\u0651\u0645\u0647 \u0645\u0646\u0630 \u0645\u062f\u0629.","\u0623\u0631\u0633\u0644 \u0631\u0633\u0627\u0644\u0629 \u0634\u0643\u0631 \u0644\u0635\u062f\u064a\u0642 \u0648\u0642\u0641 \u0645\u0639\u0643 \u064a\u0648\u0645\u064b\u0627 \u0645\u0627.","\u0627\u062f\u0639\u064f \u0635\u062f\u064a\u0642\u064b\u0627 \u0644\u0643\u0648\u0628 \u0634\u0627\u064a \u0623\u0648 \u0642\u0647\u0648\u0629 \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639.","\u0627\u0633\u062a\u0645\u0639 \u0644\u0635\u062f\u064a\u0642 \u062f\u0648\u0646 \u0623\u0646 \u062a\u0642\u0627\u0637\u0639\u0647 \u0623\u0648 \u062a\u0646\u0635\u062d\u0647."],t.s)
B.aqD=s(["\u0642\u0645 \u0628\u0639\u0645\u0644 \u0637\u064a\u0628 \u0627\u0644\u064a\u0648\u0645 \u062f\u0648\u0646 \u0623\u0646 \u064a\u0639\u0644\u0645 \u0628\u0647 \u0623\u062d\u062f.","\u0627\u0639\u062a\u0630\u0631 \u0644\u0634\u062e\u0635 \u0623\u062e\u0637\u0623\u062a \u0641\u064a \u062d\u0642\u0647\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u062e\u0637\u0623 \u0635\u063a\u064a\u0631\u064b\u0627.","\u0623\u0648\u0641\u0650 \u0628\u0648\u0639\u062f \u0635\u063a\u064a\u0631 \u0642\u0637\u0639\u062a\u0647 \u0644\u0623\u062d\u062f\u0647\u0645.","\u0627\u0645\u062a\u0646\u0639 \u0627\u0644\u064a\u0648\u0645 \u0639\u0646 \u0627\u0644\u062d\u062f\u064a\u062b \u0639\u0646 \u0623\u064a \u0634\u062e\u0635 \u0641\u064a \u063a\u064a\u0627\u0628\u0647."],t.s)
